```javascript
const MOD = 1000000007;

function modpow(a, e) {
    let res = 1;
    a %= MOD;
    while (e > 0) {
        if (e & 1) res = (res * a) % MOD;
        a = (a * a) % MOD;
        e >>= 1;
    }
    return res;
}

function modinv(x) {
    return modpow(x, MOD - 2);
}

function solve() {
    const input = require('fs').readFileSync('/dev/stdin', 'utf8').trim().split(/\s+/);
    if (input.length < 2) return;
    let n = BigInt(input[0]);
    const k = parseInt(input[1], 10);

    // Prime factorization of n
    const factors = [];
    let temp = n;
    for (let p = 2n; p * p <= temp; p++) {
        if (temp % p === 0n) {
            let cnt = 0;
            while (temp % p === 0n) {
                temp /= p;
                cnt++;
            }
            factors.push({ p: p, e: cnt });
        }
    }
    if (temp > 1n) {
        factors.push({ p: temp, e: 1 });
    }

    let ans = 1;
    for (const f of factors) {
        const p_mod = Number(f.p % BigInt(MOD));
        const e = f.e;

        // dp[j] represents probability of being at exponent j
        // Use modular arithmetic for probabilities (fractions mod MOD)
        let dp = new Array(e + 1).fill(0);
        dp[e] = 1;

        // Precompute inverses of 1..e+1
        const inv = new Array(e + 2);
        for (let i = 1; i <= e + 1; i++) {
            inv[i] = modinv(i);
        }

        for (let step = 0; step < k; step++) {
            const new_dp = new Array(e + 1).fill(0);
            // Suffix sums of dp[j] * inv[j+1]
            // new_dp[i] = sum_{j=i}^{e} dp[j] / (j+1)
            let suffix_sum = 0;
            for (let j = e; j >= 0; j--) {
                suffix_sum = (suffix_sum + dp[j] * inv[j + 1]) % MOD;
                new_dp[j] = suffix_sum;
            }
            dp = new_dp;
        }

        // Calculate expected value of p^exp
        // E = sum dp[i] * p^i
        let exp_val = 0;
        let p_pow = 1;
        for (let i = 0; i <= e; i++) {
            exp_val = (exp_val + dp[i] * p_pow) % MOD;
            p_pow = (p_pow * p_mod) % MOD;
        }
        ans = (ans * exp_val) % MOD;
    }

    console.log(ans);
}

solve();
